insert into themes (id, name_en, name_es, client_question_en, client_question_es, sort_order) values
  ('overview', 'Your gut at a glance', 'Tu intestino de un vistazo', 'How healthy is my gut overall?', '¿Qué tan saludable está mi intestino en general?', 0),
  ('digestion', 'Digestion and comfort', 'Digestión y bienestar', 'Why do I feel how I feel after eating?', '¿Por qué me siento así después de comer?', 1),
  ('metabolism', 'Metabolism and weight', 'Metabolismo y peso', 'How does my gut handle energy and sugar?', '¿Cómo maneja mi intestino la energía y el azúcar?', 2),
  ('inflammation', 'Inflammation and gut lining', 'Inflamación y barrera intestinal', 'Is my gut protecting me?', '¿Me está protegiendo mi intestino?', 3),
  ('heart', 'Heart and long term health', 'Corazón y salud a largo plazo', 'What should I keep an eye on?', '¿Qué debo vigilar?', 4),
  ('mind', 'Mind, sleep and vitamins', 'Mente, sueño y vitaminas', 'How does my gut affect my energy and mood?', '¿Cómo afecta mi intestino mi energía y estado de ánimo?', 5),
  ('safety', 'Safety screen', 'Control de seguridad', 'Is anything harmful there?', '¿Hay algo dañino presente?', 6),
  ('food', 'What to eat', 'Qué comer', 'What should I eat more or less of?', '¿Qué debería comer más o menos?', 7),
  ('supplements', 'Supplements', 'Suplementos', 'Which supplements fit me?', '¿Qué suplementos me convienen?', 8)
insert into metrics (audience, id, theme_id, kind, name_en, name_es, direction, sort_order, explanation_en, explanation_es, scale_min, scale_max) values
  ('both', 'microbiome_age', 'overview', 'headline', 'Microbiome age', 'Edad del microbioma', 'below_age', 0, 'Compares the bacterial makeup of your gut to patterns typically seen at different ages. A microbiome age below your real age is generally considered favorable.', 'Compara la composición bacteriana de tu intestino con los patrones típicos de distintas edades. Una edad del microbioma por debajo de tu edad real suele considerarse favorable.', null, null),
  ('both', 'diversity', 'overview', 'headline', 'Diversity', 'Diversidad', 'higher_better', 1, 'Measures how many different kinds of bacteria live in your gut. A wider mix is generally associated with a more resilient microbiome.', 'Mide cuántos tipos distintos de bacterias viven en tu intestino. Una mayor variedad suele asociarse con un microbioma más resiliente.', 0, 10),
  ('both', 'wellness_index', 'overview', 'headline', 'Wellness index', 'Índice de bienestar', 'categorical', 2, 'A composite score summarizing whether your overall bacterial pattern resembles profiles linked to lower or higher chronic-disease risk in research.', 'Una puntuación compuesta que resume si tu patrón bacteriano general se asemeja a perfiles asociados en estudios con un riesgo más bajo o más alto de enfermedad crónica.', null, null),
  ('both', 'f_b_ratio', 'overview', 'headline', 'F/B ratio', 'Ratio F/B', 'flag_high', 3, 'The balance between two major bacterial groups, Firmicutes and Bacteroidetes. Shifts in this ratio have been studied in relation to calorie extraction and weight regulation.', 'El equilibrio entre dos grandes grupos bacterianos, Firmicutes y Bacteroidetes. Los cambios en esta proporción se han estudiado en relación con la extracción de calorías y la regulación del peso.', null, null),
  ('both', 'bowel_mobility', 'digestion', 'gut_score', 'Bowel mobility', 'Motilidad intestinal', 'middle_best', 0, 'Reflects bacterial patterns associated with how quickly food moves through your digestive tract. The ideal range is a middle ground — not too slow, not too fast.', 'Refleja los patrones bacterianos asociados a la velocidad con la que los alimentos atraviesan tu tracto digestivo. El rango ideal es un punto intermedio: ni demasiado lento ni demasiado rápido.', null, null),
  ('both', 'carbohydrate_metabolism', 'digestion', 'gut_score', 'Carbohydrate metabolism', 'Metabolismo de carbohidratos', 'higher_better', 1, 'How effectively your gut bacteria break down and process carbohydrates from your diet.', 'Qué tan eficazmente tus bacterias intestinales descomponen y procesan los carbohidratos de tu dieta.', null, null),
  ('both', 'protein_metabolism', 'digestion', 'gut_score', 'Protein metabolism', 'Metabolismo de proteínas', 'higher_better', 2, 'How effectively your gut bacteria break down and process dietary protein.', 'Qué tan eficazmente tus bacterias intestinales descomponen y procesan las proteínas de la dieta.', null, null),
  ('both', 'fat_metabolism', 'digestion', 'gut_score', 'Fat metabolism', 'Metabolismo de grasas', 'higher_better', 3, 'How effectively your gut bacteria break down and process dietary fats.', 'Qué tan eficazmente tus bacterias intestinales descomponen y procesan las grasas de la dieta.', null, null),
  ('both', 'lactose_sensitivity', 'digestion', 'gut_score', 'Lactose sensitivity', 'Sensibilidad a la lactosa', 'lower_better', 4, 'Bacterial patterns associated with how well your gut tolerates lactose, the sugar found in dairy products.', 'Patrones bacterianos asociados con la tolerancia de tu intestino a la lactosa, el azúcar presente en los lácteos.', null, null),
  ('both', 'gluten_sensitivity', 'digestion', 'gut_score', 'Gluten sensitivity', 'Sensibilidad al gluten', 'lower_better', 5, 'Bacterial patterns associated with gluten tolerance.', 'Patrones bacterianos asociados con la tolerancia al gluten.', null, null),
  ('both', 'metabolic_score', 'metabolism', 'gut_score', 'Metabolic score', 'Puntuación metabólica', 'lower_better', 0, 'A composite measure of how your gut''s bacterial profile relates to metabolic health and energy balance.', 'Una medida compuesta de cómo se relaciona el perfil bacteriano de tu intestino con la salud metabólica y el balance energético.', null, null),
  ('both', 'sugar_index', 'metabolism', 'gut_score', 'Sugar index', 'Índice de azúcar', 'lower_better', 1, 'Bacterial patterns associated with sugar processing in the gut.', 'Patrones bacterianos asociados con el procesamiento del azúcar en el intestino.', null, null),
  ('both', 'processed_food_index', 'inflammation', 'gut_score', 'Processed food index', 'Índice de alimentos procesados', 'lower_better', 0, 'How closely your microbiome resembles bacterial profiles typically seen in diets higher in processed foods.', 'Qué tanto se parece tu microbioma a los perfiles bacterianos que suelen observarse en dietas con más alimentos procesados.', null, null),
  ('both', 'antibiotic_damage', 'inflammation', 'gut_score', 'Antibiotic damage', 'Daño por antibióticos', 'lower_better', 1, 'Signs in your gut bacteria consistent with past antibiotic use affecting microbial diversity.', 'Señales en tus bacterias intestinales compatibles con un uso previo de antibióticos que haya afectado a la diversidad microbiana.', null, null),
  ('both', 'autoimmune_index', 'inflammation', 'gut_score', 'Autoimmune index', 'Índice autoinmune', 'lower_better', 2, 'Bacterial patterns that research has associated with autoimmune-linked profiles.', 'Patrones bacterianos que la investigación ha asociado con perfiles vinculados a procesos autoinmunes.', null, null),
  ('both', 'sleep_quality', 'mind', 'gut_score', 'Sleep quality', 'Calidad del sueño', 'higher_better', 0, 'Bacterial patterns associated with sleep regulation — gut bacteria influence several compounds involved in sleep.', 'Patrones bacterianos asociados con la regulación del sueño: las bacterias intestinales influyen en varios compuestos implicados en el sueño.', null, null),
  ('both', 'vitamin_synthesis', 'mind', 'gut_score', 'Vitamin synthesis', 'Síntesis de vitaminas', 'higher_better', 1, 'How much your gut bacteria contribute to producing vitamins, like B vitamins, as a byproduct of digestion.', 'Cuánto contribuyen tus bacterias intestinales a producir vitaminas, como las del grupo B, como subproducto de la digestión.', null, null)
